// Andhra Pradesh — 16th Vidhan Sabha (matdan 13 May 2024, parinaam 4 Jun 2024; karyakaal 2024-2029).
// Group D (jile 21-26): Ananthapuramu (8), Sri Sathya Sai (6), YSR Kadapa (7), Annamayya (6), Chittoor (7), Tirupati (7) = 41 AC.
// Party tally (Group D): TDP 32, JSP 2, YSRCP 5, BJP 2 = 41. (JSP: Kodur, Tirupati. YSRCP: Badvel, Rajampet, Pulivendula, Thamballapalle, Punganur. BJP: Dharmavaram, Jammalamadugu.)
// Vijeta ECI-mirroring Wikipedia 2024 election jila-tables se cross-check kiye gaye; halafname myneta.info/AndhraPradesh2024 se (9 page header ADR render quirk ki wajah se nahi khule — unhe 2019/2014 halafname, PRS, The Hindu, IE se resolve kiya).
// CM: N. Chandrababu Naidu (TDP, Kuppam) — chauthe karyakaal, 12 Jun 2024 ko shapath (PTI/ThePrint). purva-CM: Y. S. Jagan Mohan Reddy (YSRCP, Pulivendula).
// POST-2024 FLAGS: S. Savitha (Penukonda) 12 Jun 2024 se mantri (BC Welfare, EWS, Handlooms & Textiles); Reddeppagari Madhavi (Kadapa) 12 Nov 2024 ko TDP whip (Wikipedia); V. M. Thomas (Gangadhara Nellore SC) par SC-status galat upyog ki shikayat (SC ST Rights Forum, ~Sep 2024, thecommunemag); Gurajala Jagan Mohan (Chittoor) par gunmen/SC-ST vivad (~2026); Pulivarthi Nani (Chandragiri) par 14 May 2024 ko hamla (13 giraftar, The Hindu). Venkatagiri me TDP ne pahle Lakshmi Priya ko ghoshit kiya tha, baad me Kurugondla Ramakrishna (NIE, 22 Apr 2024) — ye chunav se pahle ka badlav hai.
// NAAM-JAAL: 'Peddireddy Dwarakanatha Reddy' (Thamballapalle, YSRCP) vs 'Peddireddy Ramachandra Reddy' (Punganur, YSRCP) bhai-bhai hain — dono alag seat par hain.
// BACKGROUND_PENDING: Palle Sindhura Reddy (Puttaparthi) ke halafnama-aankde bilkul nahi mile (myneta page nahi khula, ADR ne bhi pushti ki); Daggupati Venkateswara Prasad (Anantapur Urban) ki kul sampatti (The Hindu: lagbhag Rs 53.1 crore — exact aankda nahi).


